export function isPro(){return"production"===process.env.NODE_ENV}export function deepCopy(t){return JSON.parse(JSON.stringify(t))}export function getValueType(t){return Object.prototype.toString.call(t)}export function getRandomElement(t){return t[Math.floor(Math.random()*t.length)]}export function toBoolean(t){return t=!(!t||"false"==t||0==t)}export function chunkArray(t,e){const r=[];for(let n=0;n<t.length;n+=e){const o=t.slice(n,n+e);r.push(o)}return r}export function addRouteParam(t,e){const r={};Object.entries(e).forEach(([t,e])=>{null!=e&&(r[t]=String(e))});try{const e=new URL(t);return Object.entries(r).forEach(([t,r])=>{e.searchParams.set(t,r)}),e.toString()}catch{const e=t.indexOf("#"),n=-1!==e?t.slice(e):"",o=-1!==e?t.slice(0,e):t,[c,s=""]=o.split("?"),a=new URLSearchParams(s);Object.entries(r).forEach(([t,e])=>{a.set(t,e)});const i=a.toString();let u=c;return i&&(u+="?"+i),u+n}}